import (
	"crypto/cipher"
	"crypto/ecdh"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"os"
	"strings"

	"golang.org/x/crypto/chacha20poly1305"
	"golang.org/x/crypto/hkdf"
)

var b64Unpadded = base64.RawStdEncoding

func main() {
	// Secret key from /tmp/key.txt
	// Let's create an ephemeral key pair
	ephemeralPriv, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		panic(err)
	}
	ephemeralPub := ephemeralPriv.PublicKey().Bytes()

	// Recipient pubkey from /tmp/key.txt:
	// Let's use /tmp/key.txt
	keyData, _ := os.ReadFile("/tmp/key.txt")
	secStr := strings.TrimSpace(string(keyData))
	lines := strings.Split(secStr, "\n")
	for _, l := range lines {
		l = strings.TrimSpace(l)
		if strings.HasPrefix(l, "AGE-SECRET-KEY-1") {
			secStr = l
			break
		}
	}

	// Bech32 decode secStr
	secBytes := bech32Decode(secStr)
	privKey, err := ecdh.X25519().NewPrivateKey(secBytes)
	if err != nil {
		panic(err)
	}
	pubKey := privKey.PublicKey().Bytes()

	// Shared secret = X25519(ephemeralPriv, pubKey)
	sharedSecret, err := ephemeralPriv.ECDH(privKey.PublicKey())
	if err != nil {
		panic(err)
	}

	// Salt = ephemeralPub || pubKey
	salt := append([]byte(nil), ephemeralPub...)
	salt = append(salt, pubKey...)

	// HKDF-SHA256
	wrapKey := make([]byte, 32)
	hkdfR := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/X25519"))
	if _, err := io.ReadFull(hkdfR, wrapKey); err != nil {
		panic(err)
	}

	// Generate random 16-byte file key
	fileKey := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, fileKey); err != nil {
		panic(err)
	}

	// Encrypt file key with wrapKey, nonce = zeros
	aead, err := chacha20poly1305.New(wrapKey)
	if err != nil {
		panic(err)
	}
	nonce := make([]byte, chacha20poly1305.NonceSize)
	wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

	// Format header
	hdr := fmt.Sprintf("age-encryption.org/v1\n-> X25519 %s\n%s\n--- ",
		b64Unpadded.EncodeToString(ephemeralPub),
		b64Unpadded.EncodeToString(wrappedKey))

	// HMAC key
	hmacKey := make([]byte, 32)
	hkdfH := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
	if _, err := io.ReadFull(hkdfH, hmacKey); err != nil {
		panic(err)
	}

	mac := hmac.New(sha256.New, hmacKey)
	mac.Write([]byte(hdr))
	hdrMAC := mac.Sum(nil)

	hdr += b64Unpadded.EncodeToString(hdrMAC) + "\n"

	// Payload nonce (16 random bytes)
	payloadNonce := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, payloadNonce); err != nil {
		panic(err)
	}

	// Payload key
	payloadKey := make([]byte, 32)
	hkdfP := hkdf.New(sha256.New, fileKey, payloadNonce, []byte("payload"))
	if _, err := io.ReadFull(hkdfP, payloadKey); err != nil {
		panic(err)
	}

	// Encrypt payload "hello from go\n"
	plaintext := []byte("hello from go\n")
	pAead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		panic(err)
	}

	// Nonce for chunk 0: 11 zeros + 0x01 (last chunk)
	cNonce := make([]byte, 12)
	cNonce[11] = 0x01

	ciphertext := pAead.Seal(nil, cNonce, plaintext, nil)

	var fullFile []byte
	fullFile = append(fullFile, []byte(hdr)...)
	fullFile = append(fullFile, payloadNonce...)
	fullFile = append(fullFile, ciphertext...)

	os.WriteFile("/tmp/go_age_test.age", fullFile, 0644)
	fmt.Println("Generated /tmp/go_age_test.age successfully")
}

// Bech32 helper for test
func bech32Decode(s string) []byte {
	// Simple Bech32 decode for 32 byte payload
	const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
	s = strings.ToLower(s)
	pos := strings.LastIndex(s, "1")
	dataStr := s[pos+1 : len(s)-6] // drop checksum
	var fiveBit []byte
	for _, c := range dataStr {
		fiveBit = append(fiveBit, byte(strings.IndexRune(charset, c)))
	}
	// convert 5-bit to 8-bit
	var acc int
	var bits uint
	var out []byte
	for _, v := range fiveBit {
		acc = (acc << 5) | int(v)
		bits += 5
		if bits >= 8 {
			bits -= 8
			out = append(out, byte(acc>>bits))
		}
	}
	return out[:32]
}
