func feReduce(f fe) fe {
	// Simple limb reduction
	const mask51 = (1 << 51) - 1
	c := f[0] >> 51
	f[0] &= mask51
	f[1] += c
	c = f[1] >> 51
	f[1] &= mask51
	f[2] += c
	c = f[2] >> 51
	f[2] &= mask51
	f[3] += c
	c = f[3] >> 51
	f[3] &= mask51
	f[4] += c
	c = f[4] >> 51
	f[4] &= mask51
