func convertBits(data []byte, fromBits, toBits int, pad bool) ([]int, bool) {
	var acc int
	var bits uint
	var ret []int
	maxv := (1 << toBits) - 1
	for _, value := range data {
		acc = (acc << fromBits) | int(value)
		bits += uint(fromBits)
		for bits >= uint(toBits) {
			bits -= uint(toBits)
			ret = append(ret, (acc>>bits)&maxv)
		}
	}
	if pad {
		if bits > 0 {
			ret = append(ret, (acc<<(uint(toBits)-bits))&maxv)
		}
	} else if bits >= uint(fromBits) || ((acc<<(uint(toBits)-bits))&maxv) != 0 {
		return nil, false
	}
	return ret, true
}

func convertBitsToBytes(data []int, fromBits, toBits int, pad bool) ([]byte, bool) {
	var acc int
	var bits uint
	var ret []byte
	maxv := (1 << toBits) - 1
	for _, value := range data {
		acc = (acc << fromBits) | value
		bits += uint(fromBits)
		for bits >= uint(toBits) {
			bits -= uint(toBits)
			ret = append(ret, byte((acc>>bits)&maxv))
