			quoted[k] = fmt.Sprintf("%q", p)
		}
		errorfWithHints(fmt.Sprintf("too many INPUT arguments: %s", strings.Join(quoted, " ")), []string{"only a single input file may be specified at a time"})
	}

	var inputPath string
	if len(positional) == 1 {
		inputPath = positional[0]
	}

	// Multiple stdin checks
	if (inputPath == "" || inputPath == "-") {
		for _, rf := range recipientsFiles {
			if rf == "-" {
				errorf("failed to parse recipient file \"-\": standard input is used for multiple purposes")
			}
		}
		for _, idf := range identities {
			if idf == "-" {
				errorf("reading \"-\": standard input is used for multiple purposes")
			}
		}
	}

	if isEncrypt {
		runEncrypt(inputPath, outputVal, armorVal, passphraseVal, recipients, recipientsFiles, identities, pluginFlags)
	} else {
		runDecrypt(inputPath, outputVal, identities, pluginFlags)
	}
}

func flagError(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	fmt.Fprintln(os.Stderr, usageText)
	os.Exit(2)
}

// Helper to prompt for password
func promptPassword(prompt string) (string, error) {
	var termFile *os.File
	if term.IsTerminal(int(os.Stdin.Fd())) {
		termFile = os.Stdin
	} else {
		f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			return "", fmt.Errorf("standard input is not a terminal, and /dev/tty is not available: %w", err)
		}
		defer f.Close()
		termFile = f
	}

	fmt.Fprint(termFile, prompt)
	passBytes, err := term.ReadPassword(int(termFile.Fd()))
	fmt.Fprintln(termFile)
	if err != nil {
		return "", err
	}
	return string(passBytes), nil
}

type Stanza struct {
	Type int // 0: X25519, 1: scrypt, 2: ssh-ed25519, 3: ssh-rsa, 4: plugin
	TypeStr string
	Args []string
	Body []byte
}

func runEncrypt(inputPath, outputPath string, armorVal, passphraseVal bool, recipients, recipientsFiles, identities, pluginFlags []string) {
	// TTY check for output
	if outputPath != "-" && outputPath == "" && term.IsTerminal(int(os.Stdout.Fd())) && !armorVal {
		errorfWithHints("refusing to output binary to the terminal", []string{"did you mean to use -a/--armor?", "force anyway with \"-o -\""})
	}

	var parsedRecipients []Stanza

	// 1. Recipient strings (-r)
	for i, r := range recipients {
		st, err := parseRecipientString(r, i)
		if err != nil {
			errorf("%s", err.Error())
		}
		parsedRecipients = append(parsedRecipients, st)
	}

	// 2. Recipient files (-R)
	for _, rf := range recipientsFiles {
		sts, err := parseRecipientFile(rf)
		if err != nil {
			errorf("%s", err.Error())
		}
		parsedRecipients = append(parsedRecipients, sts...)
	}

	// 3. Identity files (-i with -e)
	for _, idf := range identities {
		sts, err := parseIdentityFileForRecipients(idf)
		if err != nil {
			errorf("%s", err.Error())
		}
		parsedRecipients = append(parsedRecipients, sts...)
	}

	// 4. Passphrase mode (-p)
	if passphraseVal {
		pass, err := promptPassword("Enter passphrase (leave empty to autogenerate a secure one): ")
		if err != nil {
			errorf("could not read passphrase: %s", err.Error())
		}
		if pass == "" {
			// Autogenerate passphrase
			pass = generatePassphrase()
			fmt.Fprintf(os.Stderr, "age: using autogenerated passphrase %q\n", pass)
		} else {
			confirm, err := promptPassword("Confirm passphrase: ")
			if err != nil {
				errorf("could not read passphrase: %s", err.Error())
			}
			if pass != confirm {
				errorf("passphrases didn't match")
			}
		}

		// Create scrypt stanza
		salt := make([]byte, 16)
		rand.Read(salt)
		workFactor := 18
		N := 1 << workFactor

		scryptKey, err := scrypt.Key([]byte(pass), append([]byte("age-encryption.org/v1/scrypt"), salt...), N, 8, 1, 32)
		if err != nil {
			errorf("scrypt failed: %s", err.Error())
		}

		parsedRecipients = append(parsedRecipients, Stanza{
			Type: 1,
			TypeStr: "scrypt",
			Args: []string{b64Unpadded.EncodeToString(salt), strconv.Itoa(workFactor)},
			Body: scryptKey, // temp store scrypt key
		})
	}

	// Input source
	var inFile io.Reader
	if inputPath == "" || inputPath == "-" {
		inFile = os.Stdin
	} else {
		f, err := os.Open(inputPath)
		if err != nil {
			errorf("failed to open input file %q: %s", inputPath, err.Error())
		}
		defer f.Close()
		inFile = f
	}

	// Output destination
	var outFile io.Writer
	var outClose func()
	if outputPath == "" || outputPath == "-" {
		outFile = os.Stdout
		outClose = func() {}
	} else {
		f, err := os.Create(outputPath)
		if err != nil {
			errorf("failed to write header: %s", err.Error())
		}
		outClose = func() { f.Close() }
		outFile = f
	}
	defer outClose()

	// Generate random 16-byte file key
	fileKey := make([]byte, 16)
	rand.Read(fileKey)

	// Build header text
	var hdrBuilder strings.Builder
	hdrBuilder.WriteString("age-encryption.org/v1\n")

	for _, st := range parsedRecipients {
		if st.Type == 1 {
			// scrypt
			scryptKey := st.Body
			aead, err := chacha20poly1305.New(scryptKey)
			if err != nil {
				errorf("cipher error: %s", err.Error())
			}
			nonce := make([]byte, 12)
			wrappedKey := aead.Seal(nil, nonce, fileKey, nil)
			hdrBuilder.WriteString(fmt.Sprintf("-> scrypt %s %s\n%s\n", st.Args[0], st.Args[1], b64Unpadded.EncodeToString(wrappedKey)))
		} else if st.Type == 0 {
			// X25519
			pubKey := st.Body
			ephPriv, err := ecdh.X25519().GenerateKey(rand.Reader)
			if err != nil {
				errorf("ecdh error: %s", err.Error())
			}
			ephPub := ephPriv.PublicKey().Bytes()

			recipPub, err := ecdh.X25519().NewPublicKey(pubKey)
			if err != nil {
				errorf("invalid public key: %s", err.Error())
			}
			sharedSecret, err := ephPriv.ECDH(recipPub)
			if err != nil {
				errorf("ecdh shared secret error: %s", err.Error())
			}

			salt := append([]byte(nil), ephPub...)
			salt = append(salt, pubKey...)

			wrapKey := make([]byte, 32)
			hkdfR := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/X25519"))
			io.ReadFull(hkdfR, wrapKey)

			aead, err := chacha20poly1305.New(wrapKey)
			if err != nil {
				errorf("cipher error: %s", err.Error())
			}
			nonce := make([]byte, 12)
			wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

			hdrBuilder.WriteString(fmt.Sprintf("-> X25519 %s\n%s\n", b64Unpadded.EncodeToString(ephPub), b64Unpadded.EncodeToString(wrappedKey)))
		} else if st.Type == 2 {
			// ssh-ed25519
			// Body = ssh wire pubkey
			sshPubBytes := st.Body
			tag := sha256.Sum256(sshPubBytes)
			tagB64 := b64Unpadded.EncodeToString(tag[:4])

			// Extract 32 byte ed25519 pubkey from wire
			// Wire: 4 byte len "ssh-ed25519" + 4 byte len pubkey + 32 bytes
			pubKeyBytes := sshPubBytes[len(sshPubBytes)-32:]

			// Convert Ed25519 pubkey to X25519 pubkey
			x25519Pub, err := ed25519PublicKeyToX25519(pubKeyBytes)
			if err != nil {
				errorf("failed to convert ssh-ed25519 key: %s", err.Error())
			}

			ephPriv, err := ecdh.X25519().GenerateKey(rand.Reader)
			if err != nil {
				errorf("ecdh error: %s", err.Error())
			}
			ephPub := ephPriv.PublicKey().Bytes()

			recipPub, err := ecdh.X25519().NewPublicKey(x25519Pub)
			if err != nil {
				errorf("invalid public key: %s", err.Error())
			}
			sharedSecret, err := ephPriv.ECDH(recipPub)
			if err != nil {
				errorf("ecdh shared secret error: %s", err.Error())
			}

			salt := append([]byte(nil), ephPub...)
			salt = append(salt, x25519Pub...)

			wrapKey := make([]byte, 32)
			hkdfR := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/ssh-ed25519"))
			io.ReadFull(hkdfR, wrapKey)

			aead, err := chacha20poly1305.New(wrapKey)
			if err != nil {
				errorf("cipher error: %s", err.Error())
			}
			nonce := make([]byte, 12)
			wrappedKey := aead.Seal(nil, nonce, fileKey, nil)

			hdrBuilder.WriteString(fmt.Sprintf("-> ssh-ed25519 %s %s\n%s\n", tagB64, b64Unpadded.EncodeToString(ephPub), b64Unpadded.EncodeToString(wrappedKey)))
		} else if st.Type == 3 {
			// ssh-rsa
			sshPubBytes := st.Body
			tag := sha256.Sum256(sshPubBytes)
			tagB64 := b64Unpadded.EncodeToString(tag[:4])

			parsedKey, err := ssh.ParsePublicKey(sshPubBytes)
			if err != nil {
				errorf("failed to parse ssh-rsa key: %s", err.Error())
			}
			cryptoKey := parsedKey.(ssh.CryptoPublicKey).CryptoPublicKey()
			rsaPub := cryptoKey.(*rsa.PublicKey)

			wrappedKey, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, rsaPub, fileKey, []byte("age-encryption.org/v1/ssh-rsa"))
			if err != nil {
				errorf("failed to encrypt with ssh-rsa key: %s", err.Error())
			}

			wrappedB64 := b64Unpadded.EncodeToString(wrappedKey)
			hdrBuilder.WriteString(fmt.Sprintf("-> ssh-rsa %s\n%s\n", tagB64, wrapLines(wrappedB64, 64)))
		}
	}

	hdrPrefix := hdrBuilder.String() + "---"

	// HMAC-SHA256
	hmacKey := make([]byte, 32)
	hkdfH := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
	io.ReadFull(hkdfH, hmacKey)

	mac := hmac.New(sha256.New, hmacKey)
	mac.Write([]byte(hdrPrefix))
	hdrMAC := mac.Sum(nil)

	fullHdr := hdrPrefix + " " + b64Unpadded.EncodeToString(hdrMAC) + "\n"

	payloadNonce := make([]byte, 16)
	rand.Read(payloadNonce)

	payloadKey := make([]byte, 32)
	hkdfP := hkdf.New(sha256.New, fileKey, payloadNonce, []byte("payload"))
	io.ReadFull(hkdfP, payloadKey)

	pAead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		errorf("cipher error: %s", err.Error())
	}

	// Stream output
	var targetWriter io.Writer
	var armorFlush func()

	if armorVal {
		buf := &bytes.Buffer{}
		targetWriter = buf
		armorFlush = func() {
			armorData := wrapLines(base64.StdEncoding.EncodeToString(buf.Bytes()), 64)
			fmt.Fprintf(outFile, "-----BEGIN AGE ENCRYPTED FILE-----\n%s\n-----END AGE ENCRYPTED FILE-----\n", armorData)
		}
	} else {
		targetWriter = outFile
		armorFlush = func() {}
	}

	targetWriter.Write([]byte(fullHdr))
	targetWriter.Write(payloadNonce)

	// Stream payload chunks
	chunkBuf := make([]byte, 65536)
	var chunkIndex uint64 = 0

	for {
		n, err := io.ReadFull(inFile, chunkBuf)
		if n == 0 {
			// Empty input or EOF
			cNonce := make([]byte, 12)
			cNonce[11] = 0x01
			ciphertext := pAead.Seal(nil, cNonce, nil, nil)
			targetWriter.Write(ciphertext)
			break
		}

		// Check if next read gives EOF
		nextBuf := make([]byte, 1)
		nextN, nextErr := io.ReadFull(inFile, nextBuf)

		isLast := (nextN == 0 && (nextErr == io.EOF || nextErr == io.ErrUnexpectedEOF))

		cNonce := make([]byte, 12)
		// uint64 big endian in bytes 0..7 or 3..10
		cNonce[3] = byte(chunkIndex >> 56)
		cNonce[4] = byte(chunkIndex >> 48)
		cNonce[5] = byte(chunkIndex >> 40)
		cNonce[6] = byte(chunkIndex >> 32)
		cNonce[7] = byte(chunkIndex >> 24)
		cNonce[8] = byte(chunkIndex >> 16)
		cNonce[9] = byte(chunkIndex >> 8)
		cNonce[10] = byte(chunkIndex)
		if isLast {
			cNonce[11] = 0x01
		}

		ciphertext := pAead.Seal(nil, cNonce, chunkBuf[:n], nil)
		targetWriter.Write(ciphertext)

		if isLast {
			break
		}

		chunkIndex++
		// Re-append nextN byte to read buffer for next chunk
		inFile = io.MultiReader(bytes.NewReader(nextBuf[:nextN]), inFile)
	}

	armorFlush()
}

func parseRecipientString(r string, index int) (Stanza, error) {
	if strings.HasPrefix(r, "age1") {
		// Bech32
		hrp, bytes, err := DecodeBech32(r)
		if err != nil {
			return Stanza{}, fmt.Errorf("malformed recipient %q: %w", r, err)
		}
		if hrp == "age" && len(bytes) == 32 {
			return Stanza{Type: 0, TypeStr: "X25519", Body: bytes}, nil
		}
		// Check for plugin name (e.g. age1yubikey1...)
		if strings.HasPrefix(hrp, "age1") || strings.HasPrefix(r, "age1") {
			// Extract plugin name
			pName := strings.TrimPrefix(r, "age1")
			if idx := strings.Index(pName, "1"); idx != -1 {
				pName = pName[:idx]
			}
			// Check executable in PATH
			pluginBin := "age-plugin-" + pName
			if _, err := exec.LookPath(pluginBin); err != nil {
				hints := []string{
					fmt.Sprintf("you might want to install the %q plugin", pName),
					"visit https://age-encryption.org/awesome#plugins for a list of available plugins",
				}
				errorfWithHints(fmt.Sprintf("failed to wrap key for recipient #%d: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", index, pName, pName, pluginBin), hints)
			}
		}
		return Stanza{}, fmt.Errorf("unknown recipient type: %q", r)
	}

	if strings.HasPrefix(r, "ssh-") {
		pubKey, _, _, _, err := ssh.ParseAuthorizedKey([]byte(r))
		if err != nil {
			return Stanza{}, fmt.Errorf("malformed SSH recipient: %q: %w", r, err)
		}
		kType := pubKey.Type()
		if kType == "ssh-ed25519" {
			return Stanza{Type: 2, TypeStr: "ssh-ed25519", Body: pubKey.Marshal()}, nil
		} else if kType == "ssh-rsa" {
			return Stanza{Type: 3, TypeStr: "ssh-rsa", Body: pubKey.Marshal()}, nil
		}
		return Stanza{}, fmt.Errorf("unknown recipient type: %q", r)
	}

	return Stanza{}, fmt.Errorf("unknown recipient type: %q", r)
}

func parseRecipientFile(path string) ([]Stanza, error) {
	var r io.Reader
	if path == "-" {
		r = os.Stdin
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: failed to open recipient file: %w", path, err)
		}
		defer f.Close()
		r = f
	}

	scanner := bufio.NewScanner(r)
	var stanzas []Stanza
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		st, err := parseRecipientString(line, len(stanzas))
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: %q: malformed recipient at line %d", path, path, lineNo)
		}
		stanzas = append(stanzas, st)
	}

	if len(stanzas) == 0 {
		return nil, fmt.Errorf("failed to parse recipient file %q: %q: no recipients found", path, path)
	}
	return stanzas, nil
}

type Identity struct {
	Type int // 0: X25519, 1: SSH ed25519, 2: SSH rsa
	Body []byte // private key bytes
}

func parseIdentityFileForRecipients(path string) ([]Stanza, error) {
	identities, err := parseIdentityFile(path)
	if err != nil {
		return nil, err
	}
	var stanzas []Stanza
	for _, id := range identities {
		if id.Type == 0 {
			privKey, err := ecdh.X25519().NewPrivateKey(id.Body)
			if err != nil {
				continue
			}
			stanzas = append(stanzas, Stanza{Type: 0, TypeStr: "X25519", Body: privKey.PublicKey().Bytes()})
		} else if id.Type == 1 {
			// SSH ed25519
			pubKey := ed25519.PrivateKey(id.Body).Public().(ed25519.PublicKey)
			sshPub, _ := ssh.NewPublicKey(pubKey)
			stanzas = append(stanzas, Stanza{Type: 2, TypeStr: "ssh-ed25519", Body: sshPub.Marshal()})
		} else if id.Type == 2 {
			// SSH rsa
			rsaPriv, err := ssh.ParseRawPrivateKey(id.Body)
			if err != nil {
				continue
			}
			rsaPub, _ := ssh.NewPublicKey(&rsaPriv.(*rsa.PrivateKey).PublicKey)
			stanzas = append(stanzas, Stanza{Type: 3, TypeStr: "ssh-rsa", Body: rsaPub.Marshal()})
		}
	}
	return stanzas, nil
}

func parseIdentityFile(path string) ([]Identity, error) {
	var fileData []byte
	if path == "-" {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to read %q: %w", path, path, err)
		}
		fileData = b
	} else {
		b, err := os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("reading %q: failed to open file: %w", path, err)
		}
		fileData = b
	}

	// Check if passphrase-encrypted age file
	if bytes.HasPrefix(fileData, []byte("age-encryption.org/v1")) || bytes.HasPrefix(fileData, []byte("-----BEGIN AGE ENCRYPTED FILE-----")) {
		pass, err := promptPassword(fmt.Sprintf("Enter passphrase for identity file %q: ", path))
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", path, err)
		}
		decData, err := decryptAgeWithPassphrase(fileData, pass)
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", path, err)
		}
		fileData = decData
	}

	scanner := bufio.NewScanner(bytes.NewReader(fileData))
	var ids []Identity
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			hrp, bytes, err := DecodeBech32(line)
			if err != nil || hrp != "age-secret-key-" || len(bytes) != 32 {
				return nil, fmt.Errorf("reading %q: failed to read %q: error at line %d: unknown identity type", path, path, lineNo)
			}
			ids = append(ids, Identity{Type: 0, Body: bytes})
			continue
		}

		// Try SSH key
		if strings.HasPrefix(line, "-----BEGIN") {
			// PEM key block
			rawKey, err := ssh.ParseRawPrivateKey(fileData)
			if err == nil {
				switch k := rawKey.(type) {
				case *ed25519.PrivateKey:
					ids = append(ids, Identity{Type: 1, Body: []byte(*k)})
				case ed25519.PrivateKey:
					ids = append(ids, Identity{Type: 1, Body: []byte(k)})
				case *rsa.PrivateKey:
					ids = append(ids, Identity{Type: 2, Body: x509MarshalPrivateKey(k)})
				}
				break
			}
		}

		return nil, fmt.Errorf("reading %q: failed to read %q: error at line %d: unknown identity type", path, path, lineNo)
	}

	if len(ids) == 0 {
		return nil, fmt.Errorf("reading %q: failed to read %q: no identities found", path, path)
	}
	return ids, nil
}

func runDecrypt(inputPath, outputPath string, identities, pluginFlags []string) {
	// Read input
	var inData []byte
	if inputPath == "" || inputPath == "-" {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			errorf("failed to read input: %s", err.Error())
		}
		inData = b
	} else {
		b, err := os.ReadFile(inputPath)
		if err != nil {
			errorf("failed to open input file %q: %s", inputPath, err.Error())
		}
		inData = b
	}

	if len(inData) == 0 {
		errorf("failed to read header: parsing age header: file is empty")
	}

	// Check PEM armor
	if bytes.HasPrefix(inData, []byte("-----BEGIN AGE ENCRYPTED FILE-----")) {
		block, _ := pem.Decode(inData)
		if block == nil || block.Type != "AGE ENCRYPTED FILE" {
			errorf("failed to read header: parsing age header: invalid PEM armor")
		}
		inData = block.Bytes
	}

	// Parse header
	content := string(inData)
	introEnd := strings.Index(content, "\n")
	if introEnd == -1 {
		errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	intro := content[:introEnd+1]
	if intro != "age-encryption.org/v1\n" {
		errorf("failed to read header: parsing age header: unexpected intro: %q", intro)
	}

	macIdx := strings.Index(content, "\n--- ")
	if macIdx == -1 {
		errorf("failed to read header: parsing age header: failed to read header: EOF")
	}

	hdrPrefix := content[:macIdx+len("\n---")]
	afterMAC := content[macIdx+len("\n--- "):]
	macEnd := strings.Index(afterMAC, "\n")
	if macEnd == -1 {
		errorf("failed to read header: parsing age header: failed to read header: EOF")
	}
	macB64 := afterMAC[:macEnd]
	hdrMAC, err := b64Unpadded.DecodeString(macB64)
	if err != nil {
		errorf("failed to read header: parsing age header: malformed closing line \"--- %s\\n\": %s", macB64, err.Error())
	}

	bodyOffset := macIdx + len("\n--- ") + macEnd + 1
	payloadData := inData[bodyOffset:]

	// Parse stanzas
	stanzaLines := strings.Split(content[len(intro):macIdx], "\n")
	var stanzas []Stanza
	for i := 0; i < len(stanzaLines); {
		line := stanzaLines[i]
		if !strings.HasPrefix(line, "-> ") {
			i++
			continue
		}
		parts := strings.Split(line[3:], " ")
		sType := parts[0]
		sArgs := parts[1:]

		i++
		var bodyLines []string
		for i < len(stanzaLines) && !strings.HasPrefix(stanzaLines[i], "-> ") {
			bodyLines = append(bodyLines, stanzaLines[i])
			i++
		}
		bodyRaw, _ := b64Unpadded.DecodeString(strings.Join(bodyLines, ""))

		stanzas = append(stanzas, Stanza{
			TypeStr: sType,
			Args:    sArgs,
			Body:    bodyRaw,
		})
	}

	isScrypt := false
	for _, st := range stanzas {
		if st.TypeStr == "scrypt" {
			isScrypt = true
			break
		}
	}

	var fileKey []byte

	if isScrypt {
		if len(identities) > 0 || len(pluginFlags) > 0 {
			errorfWithHints("file is passphrase-encrypted but identities were specified with -i/--identity or -j", []string{"remove all -i/--identity/-j flags to decrypt passphrase-encrypted files"})
		}

		pass, err := promptPassword("Enter passphrase: ")
		if err != nil {
			errorf("could not read passphrase: %s", err.Error())
		}

		// Unwrap scrypt
		for _, st := range stanzas {
			if st.TypeStr == "scrypt" {
				salt, _ := b64Unpadded.DecodeString(st.Args[0])
				workFactor, _ := strconv.Atoi(st.Args[1])
				N := 1 << workFactor

				scryptKey, err := scrypt.Key([]byte(pass), append([]byte("age-encryption.org/v1/scrypt"), salt...), N, 8, 1, 32)
				if err == nil {
					aead, err := chacha20poly1305.New(scryptKey)
					if err == nil {
						fk, err := aead.Open(nil, make([]byte, 12), st.Body, nil)
						if err == nil {
							fileKey = fk
							break
						}
					}
				}
			}
		}

		if fileKey == nil {
			errorf("incorrect passphrase")
		}
	} else {
		if len(identities) == 0 && len(pluginFlags) == 0 {
			errorfWithHints("the file is not passphrase-encrypted, identities are required", []string{"specify identities with -i/--identity or -j to decrypt this file"})
		}

		// Try identities
		var parsedIdentities []Identity
		for _, idf := range identities {
			ids, err := parseIdentityFile(idf)
			if err != nil {
				errorf("%s", err.Error())
			}
			parsedIdentities = append(parsedIdentities, ids...)
		}

		for _, id := range parsedIdentities {
			for _, st := range stanzas {
				if st.TypeStr == "X25519" && id.Type == 0 {
					ephBytes, _ := b64Unpadded.DecodeString(st.Args[0])
					ephPub, err := ecdh.X25519().NewPublicKey(ephBytes)
					if err != nil {
						continue
					}
					privKey, err := ecdh.X25519().NewPrivateKey(id.Body)
					if err != nil {
						continue
					}
					sharedSecret, err := privKey.ECDH(ephPub)
					if err != nil {
						continue
					}
					pubKey := privKey.PublicKey().Bytes()
					salt := append([]byte(nil), ephBytes...)
					salt = append(salt, pubKey...)

					wrapKey := make([]byte, 32)
					hkdfR := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/X25519"))
					io.ReadFull(hkdfR, wrapKey)

					aead, err := chacha20poly1305.New(wrapKey)
					if err != nil {
						continue
					}
					fk, err := aead.Open(nil, make([]byte, 12), st.Body, nil)
					if err == nil {
						fileKey = fk
						break
					}
				} else if st.TypeStr == "ssh-ed25519" && id.Type == 1 {
					// SSH ed25519
					ephBytes, _ := b64Unpadded.DecodeString(st.Args[1])
					ephPub, err := ecdh.X25519().NewPublicKey(ephBytes)
					if err != nil {
						continue
					}

					ed25519Priv := ed25519.PrivateKey(id.Body)
					ed25519Pub := ed25519Priv.Public().(ed25519.PublicKey)
					x25519Priv, err := ed25519PrivateKeyToX25519(ed25519Priv)
					if err != nil {
						continue
					}
					x25519Pub, err := ed25519PublicKeyToX25519(ed25519Pub)
					if err != nil {
						continue
					}

					privKey, err := ecdh.X25519().NewPrivateKey(x25519Priv)
					if err != nil {
						continue
					}
					sharedSecret, err := privKey.ECDH(ephPub)
					if err != nil {
						continue
					}

					salt := append([]byte(nil), ephBytes...)
					salt = append(salt, x25519Pub...)

					wrapKey := make([]byte, 32)
					hkdfR := hkdf.New(sha256.New, sharedSecret, salt, []byte("age-encryption.org/v1/ssh-ed25519"))
					io.ReadFull(hkdfR, wrapKey)

					aead, err := chacha20poly1305.New(wrapKey)
					if err != nil {
						continue
					}
					fk, err := aead.Open(nil, make([]byte, 12), st.Body, nil)
					if err == nil {
						fileKey = fk
						break
					}
				} else if st.TypeStr == "ssh-rsa" && id.Type == 2 {
					rsaPriv, err := x509ParsePrivateKey(id.Body)
					if err != nil {
						continue
					}
					fk, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, rsaPriv, st.Body, []byte("age-encryption.org/v1/ssh-rsa"))
					if err == nil {
						fileKey = fk
						break
					}
				}
			}
			if fileKey != nil {
				break
			}
		}

		if fileKey == nil {
			errorf("no identity matched any of the recipients")
		}
	}

	// Verify Header MAC
	hmacKey := make([]byte, 32)
	hkdfH := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
	io.ReadFull(hkdfH, hmacKey)

	mac := hmac.New(sha256.New, hmacKey)
	mac.Write([]byte(hdrPrefix))
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(hdrMAC, expectedMAC) {
		errorf("bad header MAC")
	}

	if len(payloadData) < 16 {
		errorf("payload too short")
	}

	payloadNonce := payloadData[:16]
	encryptedPayload := payloadData[16:]

	payloadKey := make([]byte, 32)
	hkdfP := hkdf.New(sha256.New, fileKey, payloadNonce, []byte("payload"))
	io.ReadFull(hkdfP, payloadKey)

	pAead, err := chacha20poly1305.New(payloadKey)
	if err != nil {
		errorf("cipher error: %s", err.Error())
	}

	// Output destination
	var outFile io.Writer
	var outClose func()
	if outputPath == "" || outputPath == "-" {
		outFile = os.Stdout
		outClose = func() {}
	} else {
		f, err := os.Create(outputPath)
		if err != nil {
			errorf("failed to open output file: %s", err.Error())
		}
		outClose = func() { f.Close() }
		outFile = f
	}
	defer outClose()

	// Decrypt payload chunks
	chunkSize := 65536 + 16
	var chunkIndex uint64 = 0

	for offset := 0; offset < len(encryptedPayload); offset += chunkSize {
		end := offset + chunkSize
		if end > len(encryptedPayload) {
			end = len(encryptedPayload)
		}
		chunkData := encryptedPayload[offset:end]
		isLast := (end == len(encryptedPayload))

		cNonce := make([]byte, 12)
		cNonce[3] = byte(chunkIndex >> 56)
		cNonce[4] = byte(chunkIndex >> 48)
		cNonce[5] = byte(chunkIndex >> 40)
		cNonce[6] = byte(chunkIndex >> 32)
		cNonce[7] = byte(chunkIndex >> 24)
		cNonce[8] = byte(chunkIndex >> 16)
		cNonce[9] = byte(chunkIndex >> 8)
		cNonce[10] = byte(chunkIndex)
		if isLast {
			cNonce[11] = 0x01
		}

		plain, err := pAead.Open(nil, cNonce, chunkData, nil)
		if err != nil {
			errorf("failed to decrypt payload: %s", err.Error())
		}
		outFile.Write(plain)
		chunkIndex++
	}
}

func wrapLines(s string, width int) string {
	var sb strings.Builder
	for i := 0; i < len(s); i += width {
		end := i + width
		if end > len(s) {
			end = len(s)
		}
		sb.WriteString(s[i:end])
		if end < len(s) {
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

