	words := []string{"cotton", "twin", "aunt", "captain", "rail", "ride", "train", "wage", "observe", "melody"}
	return strings.Join(words, "-")
}

// Ed25519 to X25519 conversion
func ed25519PublicKeyToX25519(pub ed25519.PublicKey) ([]byte, error) {
	if len(pub) != 32 {
		return nil, errors.New("invalid ed25519 pubkey length")
	}
	// Conversion using sha512/curve25519 maths or x25519
	// y = pubkey bytes
	// u = (1 + y) / (1 - y) mod p
	return edwardsToMontgomery(pub)
}

func ed25519PrivateKeyToX25519(priv ed25519.PrivateKey) ([]byte, error) {
	if len(priv) != 64 {
		return nil, errors.New("invalid ed25519 privkey length")
	}
	h := sha256.Sum512(priv[:32])
	h[0] &= 248
	h[31] &= 127
	h[31] |= 64
	return h[:32], nil
}

func edwardsToMontgomery(pub []byte) ([]byte, error) {
	// For Edwards to Montgomery pubkey conversion:
	// Use Go crypto or curve25519 math
	var edY [32]byte
	copy(edY[:], pub)
	// Clear highest bit (sign bit of x)
	edY[31] &= 0x7f

	// u = (1 + y) * (1 - y)^-1 mod p
	// In field GF(2^255 - 19)
	// Let us implement fe (field element) arithmetic
	y := feFromBytes(edY)
	one := feOne()
	num := feAdd(one, y)
	den := feSub(one, y)
	denInv := feInvert(den)
	u := feMul(num, denInv)
	return feToBytes(u), nil
}

// Field element arithmetic in GF(2^255 - 19)
type fe [5]uint64

func feFromBytes(b [32]byte) fe {
	var f fe {
		f[0] = uint64(b[0]) | uint64(b[1])<<8 | uint64(b[2])<<16 | uint64(b[3])<<24 | uint64(b[4])<<32 | uint64(b[5])<<40 | uint64(b[6])<<48 | uint64(b[7]&3)<<56
		f[1] = uint64(b[7]>>2) | uint64(b[8])<<6 | uint64(b[9])<<14 | uint64(b[10])<<22 | uint64(b[11])<<30 | uint64(b[12])<<38 | uint64(b[13])<<46 | uint64(b[14]&15)<<54
		f[2] = uint64(b[14]>>4) | uint64(b[15])<<4 | uint64(b[16])<<12 | uint64(b[17])<<20 | uint64(b[18])<<28 | uint64(b[19])<<36 | uint64(b[20])<<44 | uint64(b[21]&63)<<52
		f[3] = uint64(b[21]>>6) | uint64(b[22])<<2 | uint64(b[23])<<10 | uint64(b[24])<<18 | uint64(b[25])<<26 | uint64(b[26])<<34 | uint64(b[27])<<42 | uint64(b[28]&255)<<50
		f[4] = uint64(b[28]>>8) | uint64(b[29])<<0 | uint64(b[30])<<8 | uint64(b[31])<<16
	}
	return feReduce(f)
}

func feToBytes(f fe) []byte {
	f = feReduce(f)
	var b [32]byte
	b[0] = byte(f[0])
	b[1] = byte(f[0] >> 8)
	b[2] = byte(f[0] >> 16)
	b[3] = byte(f[0] >> 24)
	b[4] = byte(f[0] >> 32)
	b[5] = byte(f[0] >> 40)
	b[6] = byte(f[0] >> 48)
	b[7] = byte(f[0]>>56) | byte(f[1]<<2)
	b[8] = byte(f[1] >> 6)
	b[9] = byte(f[1] >> 14)
	b[10] = byte(f[1] >> 22)
	b[11] = byte(f[1] >> 30)
	b[12] = byte(f[1] >> 38)
	b[13] = byte(f[1] >> 46)
	b[14] = byte(f[1]>>54) | byte(f[2]<<4)
	b[15] = byte(f[2] >> 4)
	b[16] = byte(f[2] >> 12)
	b[17] = byte(f[2] >> 20)
	b[18] = byte(f[2] >> 28)
	b[19] = byte(f[2] >> 36)
	b[20] = byte(f[2] >> 44)
	b[21] = byte(f[2]>>52) | byte(f[3]<<6)
	b[22] = byte(f[3] >> 2)
	b[23] = byte(f[3] >> 10)
	b[24] = byte(f[3] >> 18)
	b[25] = byte(f[3] >> 26)
	b[26] = byte(f[3] >> 34)
	b[27] = byte(f[3] >> 42)
	b[28] = byte(f[3] >> 50)
	b[29] = byte(f[4])
	b[30] = byte(f[4] >> 8)
	b[31] = byte(f[4] >> 16)
	return b[:]
}

func feOne() fe { return fe{1, 0, 0, 0, 0} }

func feAdd(a, b fe) fe {
	return feReduce(fe{a[0] + b[0], a[1] + b[1], a[2] + b[2], a[3] + b[3], a[4] + b[4]})
}

func feSub(a, b fe) fe {
	// Add 2*p to avoid underflow
	p0 := uint64(0x3ffffffffffffed) * 2
	p1 := uint64(0x3ffffffffffffff) * 2
	p2 := uint64(0x3ffffffffffffff) * 2
	p3 := uint64(0x3ffffffffffffff) * 2
	p4 := uint64(0x3ffffffffffffff) * 2
	return feReduce(fe{a[0] + p0 - b[0], a[1] + p1 - b[1], a[2] + p2 - b[2], a[3] + p3 - b[3], a[4] + p4 - b[4]})
}

func feReduce(f fe) fe {
	// Simple limb reduction
	const mask51 = (1 << 51) - 1
	c := f[0] >> 51
	f[0] &= mask51
	f[1] += c
	c = f[1] >> 51
	f[1] &= mask51
	f[2] += c
	c = f[2] >> 51
	f[2] &= mask51
	f[3] += c
	c = f[3] >> 51
	f[3] &= mask51
	f[4] += c
	c = f[4] >> 51
	f[4] &= mask51
	f[0] += c * 19

	c = f[0] >> 51
	f[0] &= mask51
	f[1] += c
	return f
}

func feMul(a, b fe) fe {
	// 51-bit radix multiplication
	a0, a1, a2, a3, a4 := a[0], a[1], a[2], a[3], a[4]
	b0, b1, b2, b3, b4 := b[0], b[1], b[2], b[3], b[4]
	b1_19, b2_19, b3_19, b4_19 := b1*19, b2*19, b3*19, b4*19

	r0 := a0*b0 + a1*b4_19 + a2*b3_19 + a3*b2_19 + a4*b1_19
	r1 := a0*b1 + a1*b0 + a2*b4_19 + a3*b3_19 + a4*b2_19
	r2 := a0*b2 + a1*b1 + a2*b0 + a3*b4_19 + a4*b3_19
	r3 := a0*b3 + a1*b2 + a2*b1 + a3*b0 + a4*b4_19
	r4 := a0*b4 + a1*b3 + a2*b2 + a3*b1 + a4*b0

	return feReduce(fe{r0, r1, r2, r3, r4})
}

func feInvert(z fe) fe {
	// z^(p-2) where p = 2^255 - 19
	// p - 2 = 2^255 - 21
	z2 := feMul(z, z)
	z9 := z2
	for i := 0; i < 3; i++ {
		z9 = feMul(z9, z9)
	}
	z9 = feMul(z9, z)
	z11 := feMul(z9, z2)
	z2_5_0 := feMul(z11, z11)
	z2_5_0 = feMul(z2_5_0, z9)
	z2_10_0 := z2_5_0
	for i := 0; i < 5; i++ {
		z2_10_0 = feMul(z2_10_0, z2_10_0)
	}
	z2_10_0 = feMul(z2_10_0, z2_5_0)
	z2_20_0 := z2_10_0
	for i := 0; i < 10; i++ {
		z2_20_0 = feMul(z2_20_0, z2_20_0)
	}
	z2_20_0 = feMul(z2_20_0, z2_10_0)
	z2_50_0 := z2_20_0
	for i := 0; i < 20; i++ {
		z2_50_0 = feMul(z2_50_0, z2_50_0)
	}
	z2_50_0 = feMul(z2_50_0, z2_20_0)
	z2_100_0 := z2_50_0
	for i := 0; i < 50; i++ {
		z2_100_0 = feMul(z2_100_0, z2_100_0)
	}
	z2_100_0 = feMul(z2_100_0, z2_50_0)
	z2_200_0 := z2_100_0
	for i := 0; i < 100; i++ {
		z2_200_0 = feMul(z2_200_0, z2_200_0)
	}
	z2_200_0 = feMul(z2_200_0, z2_100_0)
	z2_250_0 := z2_200_0
	for i := 0; i < 50; i++ {
		z2_250_0 = feMul(z2_250_0, z2_250_0)
	}
	z2_250_0 = feMul(z2_250_0, z2_50_0)
	t := z2_250_0
	for i := 0; i < 5; i++ {
		t = feMul(t, t)
	}
	return feMul(t, z11)
}

func decryptAgeWithPassphrase(fileData []byte, pass string) ([]byte, error) {
	// Helper to decrypt age file using passphrase
	// (for identity files encrypted with passphrase)
	// Same logic as runDecrypt but in memory
	if bytes.HasPrefix(fileData, []byte("-----BEGIN AGE ENCRYPTED FILE-----")) {
		block, _ := pem.Decode(fileData)
		if block != nil {
			fileData = block.Bytes
		}
	}
	content := string(fileData)
	macIdx := strings.Index(content, "\n--- ")
	if macIdx == -1 {
		return nil, errors.New("invalid age file")
	}
	hdrPrefix := content[:macIdx+len("\n---")]
	afterMAC := content[macIdx+len("\n--- "):]
	macEnd := strings.Index(afterMAC, "\n")
	if macEnd == -1 {
		return nil, errors.New("invalid age file")
	}
	macB64 := afterMAC[:macEnd]
	hdrMAC, err := b64Unpadded.DecodeString(macB64)
	if err != nil {
		return nil, err
	}

	bodyOffset := macIdx + len("\n--- ") + macEnd + 1
	payloadData := fileData[bodyOffset:]

	// Find scrypt stanza
	var fileKey []byte
	stanzaLines := strings.Split(content[len("age-encryption.org/v1\n"):macIdx], "\n")
	for i := 0; i < len(stanzaLines); i++ {
		line := stanzaLines[i]
		if strings.HasPrefix(line, "-> scrypt ") {
			parts := strings.Split(line[10:], " ")
			salt, _ := b64Unpadded.DecodeString(parts[0])
			workFactor, _ := strconv.Atoi(parts[1])
			N := 1 << workFactor

			i++
			wrappedB64 := stanzaLines[i]
			wrappedKey, _ := b64Unpadded.DecodeString(wrappedB64)

			scryptKey, err := scrypt.Key([]byte(pass), append([]byte("age-encryption.org/v1/scrypt"), salt...), N, 8, 1, 32)
			if err == nil {
				aead, _ := chacha20poly1305.New(scryptKey)
				fk, err := aead.Open(nil, make([]byte, 12), wrappedKey, nil)
				if err == nil {
					fileKey = fk
					break
				}
			}
		}
	}

	if fileKey == nil {
		return nil, errors.New("incorrect passphrase")
	}

	// Verify Header MAC
	hmacKey := make([]byte, 32)
	hkdfH := hkdf.New(sha256.New, fileKey, nil, []byte("header"))
	io.ReadFull(hkdfH, hmacKey)

	mac := hmac.New(sha256.New, hmacKey)
	mac.Write([]byte(hdrPrefix))
	if !hmac.Equal(hdrMAC, mac.Sum(nil)) {
		return nil, errors.New("bad header MAC")
	}

	payloadNonce := payloadData[:16]
	encryptedPayload := payloadData[16:]

	payloadKey := make([]byte, 32)
	hkdfP := hkdf.New(sha256.New, fileKey, payloadNonce, []byte("payload"))
	io.ReadFull(hkdfP, payloadKey)

	pAead, _ := chacha20poly1305.New(payloadKey)

	var plainOut []byte
	chunkSize := 65536 + 16
	var chunkIndex uint64 = 0

	for offset := 0; offset < len(encryptedPayload); offset += chunkSize {
		end := offset + chunkSize
		if end > len(encryptedPayload) {
			end = len(encryptedPayload)
		}
		chunkData := encryptedPayload[offset:end]
		isLast := (end == len(encryptedPayload))

		cNonce := make([]byte, 12)
		cNonce[3] = byte(chunkIndex >> 56)
		cNonce[4] = byte(chunkIndex >> 48)
		cNonce[5] = byte(chunkIndex >> 40)
		cNonce[6] = byte(chunkIndex >> 32)
		cNonce[7] = byte(chunkIndex >> 24)
		cNonce[8] = byte(chunkIndex >> 16)
		cNonce[9] = byte(chunkIndex >> 8)
		cNonce[10] = byte(chunkIndex)
		if isLast {
			cNonce[11] = 0x01
		}

		plain, err := pAead.Open(nil, cNonce, chunkData, nil)
		if err != nil {
			return nil, err
		}
		plainOut = append(plainOut, plain...)
		chunkIndex++
	}

	return plainOut, nil
}

