	x25519PrivBytes := ed25519PrivToX25519(edPriv)
	x25519PubBytes, _ := edwardsToMontgomery(edPub)

	ephBytes, _ := b64Unpadded.DecodeString(ephB64)
	wrappedKey, _ := b64Unpadded.DecodeString(wrappedB64)

	privKey, _ := ecdh.X25519().NewPrivateKey(x25519PrivBytes)
	ephPub, _ := ecdh.X25519().NewPublicKey(ephBytes)

	sharedSecret, _ := privKey.ECDH(ephPub)

	tagBytes, _ := b64Unpadded.DecodeString(tagB64)
	wireSha := sha256Sum(sshWire)

	// Try all combinations
	for _, sec := range [][]byte{sharedSecret, x25519PrivBytes, ephBytes, edPriv[:32], edPub, x25519PubBytes} {
		for _, saltPrefix := range [][]byte{ephBytes, tagBytes, wireSha, sshWire, edPub, x25519PubBytes, nil} {
			for _, saltSuffix := range [][]byte{sshWire, wireSha, tagBytes, edPub, x25519PubBytes, ephBytes, nil} {
				salt := append([]byte(nil), saltPrefix...)
				salt = append(salt, saltSuffix...)

				for _, infoStr := range []string{
					"age-encryption.org/v1/ssh-ed25519",
					"age-encryption.org/v1/ssh-ed25519/" + tagB64,
					"age-encryption.org/v1/ssh",
					"ssh-ed25519",
					"",
				} {
					for _, nonce := range [][]byte{make([]byte, 12), tagBytes, wireSha[:12]} {
						if len(nonce) != 12 {
							continue
						}
						wrapKey := make([]byte, 32)
						hkdfR := hkdf.New(sha256.New, sec, salt, []byte(infoStr))
						io.ReadFull(hkdfR, wrapKey)

						aead, err := chacha20poly1305.New(wrapKey)
						if err != nil {
							continue
						}

						fk, err := aead.Open(nil, nonce, wrappedKey, nil)
						if err == nil {
							fmt.Printf("SUCCESS! info=%q, saltLen=%d, fileKey=%x\n", infoStr, len(salt), fk)
							return
						}
					}
				}
			}
		}
	}
	fmt.Println("No match in find_ssh")
}

func sha256Sum(b []byte) []byte {
	s := sha256.Sum256(b)
	return s[:]
}

func ed25519PrivToX25519(priv ed25519.PrivateKey) []byte {
	h := sha512.Sum512(priv[:32])
	h[0] &= 248
	h[31] &= 127
	h[31] |= 64
	return h[:32]
}

func edwardsToMontgomery(pub []byte) ([]byte, error) {
	P := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 255), big.NewInt(19))
	yBytes := make([]byte, 32)
	copy(yBytes, pub)
	yBytes[31] &= 0x7f
	for i := 0; i < 16; i++ {
		yBytes[i], yBytes[31-i] = yBytes[31-i], yBytes[i]
	}
	y := new(big.Int).SetBytes(yBytes)
	one := big.NewInt(1)
	num := new(big.Int).Mod(new(big.Int).Add(one, y), P)
	den := new(big.Int).Mod(new(big.Int).Sub(one, y), P)
	denInv := new(big.Int).ModInverse(den, P)
	u := new(big.Int).Mod(new(big.Int).Mul(num, denInv), P)
	uBytes := u.Bytes()
	padded := make([]byte, 32)
	copy(padded[32-len(uBytes):], uBytes)
	for i := 0; i < 16; i++ {
		padded[i], padded[31-i] = padded[31-i], padded[i]
	}
	return padded, nil
}
